def client_files(query,base,items,skills,notes=None,skill_types=None):
 files,summary=_icon50122_previous(query,base,items,skills,notes,skill_types)
 import base64,re
 files['icon/item/custom_chest_50122.tga']=base64.b64decode('')
 name='gamedata/item_list.txt'
 if name not in files:raise RuntimeError('Brak item_list: ikona nie zostala zastosowana.')
 pattern=rb'(?m)^(50122[ \t]+[^ \t\r\n]+[ \t]+)[^ \t\r\n]+'
 files[name],count=re.subn(pattern,lambda m:m.group(1)+b'icon/item/custom_chest_50122.tga',files[name])
 if count!=1:raise RuntimeError('Nie znaleziono jednego wpisu 50122.')
 return files,summary
